import {SAMPLE_PLAN,SCENARIOS,clone} from './core/fixtures.js';
import {validatePlan,schedule,rank,summary,approveCandidate,fingerprint,PROFILES} from './core/engine.js';
import {runProof} from './core/proof.js';
import {decisionBrief,briefText} from './core/assurance.js';
import {runAgent} from './core/agent.js';
const $=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
let plan=clone(SAMPLE_PLAN),decision=null,selected=null,profile='balanced',previous=null,receipts=[],decisionBase=null,lastDecision=null,apiMode='local-rules',busy=false;
try{const stored=JSON.parse(localStorage.getItem('deliveryguard.v1')||'null');if(stored){validatePlan(stored.plan);plan=stored.plan;receipts=Array.isArray(stored.receipts)?stored.receipts.slice(-20):[];lastDecision=stored.lastDecision||null;decisionBase=stored.decisionBase||null;}}catch{localStorage.removeItem('deliveryguard.v1');}
function notify(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);$('notice').hidden=false;}
function persist(){try{localStorage.setItem('deliveryguard.v1',JSON.stringify({plan,receipts:receipts.slice(-20),lastDecision,decisionBase}));}catch{notify('Browser storage is unavailable. Export the decision packet before closing.',true);}}
function candidate(){return decision?.result?.candidates.find(c=>c.id===selected)??null;}
function updateStats(){const m=schedule(plan);$('project-name').textContent=plan.name;$('client-name').textContent=`${plan.client||'Local client project'} · Fixed-fee engagement`;$('revenue').textContent=money(plan.revenue);$('cost').textContent=money(m.cost);$('budget-note').textContent=`${money(plan.budget)} budget · ${money(m.headroom)} remaining`;$('margin').textContent=(m.marginRate*100).toFixed(1)+'%';$('margin-note').textContent=`${money(m.margin)} contribution · ${(plan.minMargin*100).toFixed(0)}% floor`;$('deadline').textContent='Day '+plan.deadline;$('finish-note').textContent=`Finish day ${m.finish} · ${m.slack} ${m.slack===1?'day':'days'} of buffer`;$('undo').disabled=!previous;}
function drawTimeline(){
  const base=decision?.result?.impacted??schedule(plan),c=candidate(),next=c?.metrics;
  const all=[...base.rows,...(next?.rows||[])],max=Math.max(plan.deadline,...all.map(t=>t.finish),1)*1.08;
  const width=680,labelWidth=175,plot=width-labelWidth-20,rows=base.rows,rowHeight=34,height=rows.length*rowHeight+38;
  const x=d=>labelWidth+d/max*plot;
  let svg=`<svg viewBox="0 0 ${width} ${height}" xmlns="http://www.w3.org/2000/svg" aria-label="Schedule in working days">`;
  for(let i=0;i<=5;i++){const day=Math.round(max*i/5);svg+=`<line class="gridline" x1="${x(day)}" x2="${x(day)}" y1="19" y2="${height-15}"/><text class="axis" x="${x(day)}" y="12" text-anchor="middle">D${day}</text>`;}
  const effectiveDeadline=c?.plan.deadline??(decision?.interpretation?.disruption?.type==='deadline'?decision.interpretation.disruption.value:plan.deadline);
  svg+=`<line class="deadline-line" x1="${x(effectiveDeadline)}" x2="${x(effectiveDeadline)}" y1="18" y2="${height-15}"/><text class="axis" x="${x(effectiveDeadline)-3}" y="${height-2}" text-anchor="end">Deadline D${effectiveDeadline}</text>`;
  rows.forEach((t,i)=>{const y=26+i*rowHeight,recovery=next?.rows.find(r=>r.id===t.id);svg+=`<text class="task-label" x="0" y="${y+13}">${escape(t.name.length>26?t.name.slice(0,24)+'…':t.name)}${t.required?'':' ◦'}</text><rect class="${t.required?'bar-baseline':'bar-optional'}" x="${x(t.start)}" y="${y}" width="${Math.max(3,t.days/max*plot)}" height="${next?8:15}" rx="3"><title>${escape(t.name)}: day ${t.start}–${t.finish}, ${escape(t.owner)}</title></rect>`;if(recovery)svg+=`<rect class="bar-proposed" x="${x(recovery.start)}" y="${y+12}" width="${Math.max(3,recovery.days/max*plot)}" height="8" rx="3"><title>Recovery: day ${recovery.start}–${recovery.finish}, ${escape(recovery.owner)}</title></rect>`;else if(next)svg+=`<text class="axis" x="${labelWidth}" y="${y+21}">Deferred by client agreement</text>`;});
  $('timeline').innerHTML=svg+'</svg>';$('timeline-state').textContent=next?'Disrupted → recovery':decision?.result?'Disrupted plan':'Current plan';
  $('impact').innerHTML=decision?.result?`<span>Do nothing: day ${base.finish} · ${money(base.penalty)} lateness exposure</span><span>${next?`Recovery: day ${next.finish} · ${money(next.margin)} margin`:'No feasible option evaluated'}</span>`:`<span>${plan.tasks.length} tasks · ${plan.resources.length} resources</span><span>One task per resource at a time</span>`;
}
function renderTrace(){const trace=decision?.trace||[];$('trace-status').textContent=decision?`${trace.length} steps · ${decision.elapsedMs} ms`:'Awaiting input';$('trace').innerHTML=trace.length?trace.map(t=>`<li><span class="trace-dot">${t.status==='passed'?'✓':t.step}</span><div><strong>${escape(t.role)} <span class="eval-category">/ ${escape(t.tool.replaceAll('_',' '))}</span></strong><small>${escape(t.detail)}</small></div></li>`).join(''):'<li class="trace-placeholder">Coordinator → Interpreter → Planner → Verifier → Your approval</li>';}
function renderResults(){
  const r=decision?.result;$('empty').hidden=!!r;$('results').hidden=!r;renderTrace();drawTimeline();if(!r){$('assurance').innerHTML='';return;}
  const c=candidate(),winner=r.candidates.find(c=>c.id===r.winnerId);
  $('recommendation').innerHTML=`<span class="eyebrow">${winner?'RECOMMENDED NEXT MOVE':'NO FEASIBLE RECOVERY FOUND'}</span><p>${escape(summary(winner,r))}</p>${decision.interpretation?`<div class="risk-line">Review interpretation: ${escape(decision.interpretation.disruption.type)} · ${escape(decision.interpretation.disruption.target)} → ${escape(decision.interpretation.disruption.value)} · ${escape(decision.interpretation.mode)}</div>`:''}`;
  const feasible=r.candidates.filter(c=>c.feasible);
  $('candidates').innerHTML=feasible.slice(0,12).map(c=>`<button class="candidate ${c.id===selected?'selected':''}" data-candidate="${escape(c.id)}" aria-pressed="${c.id===selected}"><div><span class="pill ${c.status}">${c.status==='provisional'?'Needs verification':'Declared constraints pass'}</span> ${c.id===r.winnerId?'<span class="pill subtle">Recommended</span>':''}</div><div class="candidate-name">${escape(c.label)}</div><div class="candidate-numbers"><div><strong>${money(c.metrics.cost)}</strong><small>${money(c.metrics.headroom)} budget headroom</small></div><div><strong>Day ${c.metrics.finish}</strong><small>${c.metrics.slack} days of buffer</small></div></div><div class="candidate-meta">${c.patch.length} ${c.patch.length===1?'change':'changes'} · ${(c.objectives.lostValue*100).toFixed(0)}% task value deferred · ${c.frontier?'Pareto frontier':'Dominated option'}</div></button>`).join('');
  $('search-note').textContent=`${r.candidates.length} candidates · ${r.visited} assignments · ${r.truncated?'Search bound reached; optimum not assured':'All declared combinations explored'}${feasible.length>12?' · top 12 shown':''}`;
  $('rejected').innerHTML=$('show-rejected').checked?r.candidates.filter(c=>!c.feasible).map(c=>`<div class="rejected-item"><strong>${escape(c.label)}</strong><span>${c.violations.map(v=>escape(v.message)).join('<br>')}</span></div>`).join(''):'';
  if(!c){$('diff').innerHTML='';$('assurance').innerHTML='';return;}
  const brief=decisionBrief(c,decision.result,decisionBase),e=brief.economics;
  $('assurance').innerHTML=`<section class="decision-assurance"><div class="section-top"><div><span class="step-label">BEFORE YOU COMMIT</span><h3>Does this recovery survive a slip?</h3></div><button class="button secondary small" id="download-brief">↓ Decision brief</button></div><div class="business-comparison"><article><small>Contribution if you wait</small><strong>${money(e.waitingContribution)}</strong></article><article><small>Selected recovery contribution</small><strong>${money(e.recoveryContribution)}</strong></article><article><small>Difference versus waiting</small><strong>${money(e.contributionGain)}</strong></article></div><p class="muted">${money(e.budgetBuffer)} budget buffer · ${e.deadlineBuffer} working days of deadline buffer. Contribution includes declared lateness costs.</p><div class="table-wrap"><table><thead><tr><th>What-if shock</th><th>Cost / finish</th><th>Constraint outcome</th></tr></thead><tbody>${brief.stress.map(s=>`<tr><td>${escape(s.name)}</td><td>${money(s.metrics.cost)} / day ${s.metrics.finish}</td><td class="${s.passed?'eval-pass':'eval-fail'}">${s.passed?'Passes declared constraints':s.violations.map(v=>escape(v.message)).join('<br>')}</td></tr>`).join('')}</tbody></table></div><p class="muted">Fixed stress scenarios, not likelihoods or guarantees. The selected patch stays fixed; these checks do not search for a second recovery.</p></section>`;
  $('download-brief').addEventListener('click',()=>download(briefText(brief),'deliveryguard-brief.txt','text/plain'));
  const taskName=id=>plan.tasks.find(t=>t.id===id)?.name||id;
  $('diff').innerHTML=`<div class="diff"><div class="diff-title"><h3>Selected option · ${c.patch.length} task ${c.patch.length===1?'change':'changes'}</h3><button class="button primary small" id="review-approval">Review & approve →</button></div>${c.verification.length?`<p class="risk-line">Before applying: ${c.verification.map(escape).join('; ')}.</p>`:''}<div class="table-wrap"><table><thead><tr><th>Deliverable</th><th>Change</th><th>Cost impact</th><th>Scope</th></tr></thead><tbody>${c.patch.length?c.patch.map(p=>`<tr><td>${escape(taskName(p.taskId))}</td><td>${p.action==='defer'?'Defer to a later engagement':`${escape(p.before.owner)} → ${escape(p.after.owner)} · ${p.before.days} → ${p.after.days} days`}</td><td>${money((p.after?.cost||0)-p.before.cost)}</td><td>${p.action==='defer'?'Client agreement required':'Required scope preserved'}</td></tr>`).join(''):'<tr><td colspan="4">No task changes. Only the interpreted constraint changes.</td></tr>'}</tbody></table></div></div>`;
  $('review-approval').addEventListener('click',openApproval);
  document.querySelectorAll('[data-candidate]').forEach(b=>b.addEventListener('click',()=>{selected=b.dataset.candidate;renderResults();}));
}
async function analyze(){
  if(busy)return;busy=true;$('analyze').disabled=true;$('analyze').textContent='Evaluating recovery…';$('notice').hidden=true;
  try{
    decisionBase=clone(plan);const interpreter=$('live-ai').checked?async(input,plan)=>{const r=await fetch('/api/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({input,plan}),signal:AbortSignal.timeout(16000)});const data=await r.json();if(!r.ok)throw new Error(data.error||'AI request failed.');return data;}:null;
    decision=await runAgent(plan,$('input').value,{profile,interpreter});lastDecision=clone(decision);selected=decision.result?.winnerId??null;persist();
    if(decision.status==='clarify'||decision.status==='blocked')notify(decision.interpretation.reason,true);
    else if(decision.status==='no_solution')notify('No explored option passes all hard constraints. Review rejected candidates and adjust the plan or approved alternatives.',true);
    renderResults();
  }catch(e){decision=null;selected=null;renderResults();notify(e.message+' No plan changes were applied.',true);}
  finally{busy=false;$('analyze').disabled=false;$('analyze').innerHTML='Analyze disruption <span>→</span>';}
}
function openApproval(){const c=candidate();if(!c)return;$('approval-check').checked=false;$('apply').disabled=true;$('approval-body').innerHTML=`<p>${escape(summary(c,decision.result))}</p>${c.patch.some(p=>p.action==='defer')?'<p class="risk-line">Optional deliverables will leave this engagement. Confirm client agreement before approval.</p>':''}${c.verification.length?`<label class="check"><input id="verify-external" type="checkbox"> I have confirmed: ${c.verification.map(escape).join('; ')}.</label>`:''}`;$('approval').showModal();$('approval-body').querySelector('input')?.addEventListener('change',updateApproval);}
function updateApproval(){$('apply').disabled=!$('approval-check').checked||!!($('verify-external')&&!$('verify-external').checked);}
$('approval-check').addEventListener('change',updateApproval);
$('apply').addEventListener('click',()=>{try{const c=candidate(),confirmed=c.patch.filter(p=>p.alternativeId).map(p=>p.alternativeId),approved=approveCandidate(plan,decision.result,c.id,{approval:$('approval-check').checked,confirmed});lastDecision=clone(decision);previous=clone(plan);plan=approved.plan;receipts.push({...approved.receipt,approvedAt:new Date().toISOString()});persist();$('approval').close();decision=null;selected=null;updateStats();renderResults();notify(`Recovery approved locally. ${c.patch.length} task ${c.patch.length===1?'change':'changes'} applied. You can undo this approval or export its receipt.`);}catch(e){$('approval').close();notify(e.message,true);}});
$('close-approval').addEventListener('click',()=>$('approval').close());
$('analyze').addEventListener('click',analyze);
$('input').value=SCENARIOS[0].text;
$('scenarios').innerHTML=SCENARIOS.map((s,i)=>`<button class="scenario ${i===0?'active':''}" data-scenario="${s.id}">${escape(s.label)}</button>`).join('');
document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-scenario]').forEach(x=>x.classList.toggle('active',x===b));$('input').value=SCENARIOS.find(s=>s.id===b.dataset.scenario).text;}));
document.querySelectorAll('[data-profile]').forEach(b=>b.addEventListener('click',()=>{profile=b.dataset.profile;document.querySelectorAll('[data-profile]').forEach(x=>x.classList.toggle('selected',x===b));if(decision?.result){decision.result.profile=profile;decision.result.candidates=rank(decision.result.candidates,decisionBase,profile);decision.result.winnerId=decision.result.candidates.find(c=>c.feasible)?.id??null;selected=decision.result.winnerId;const last=decision.trace.at(-1);if(last)last.detail=summary(candidate(),decision.result);lastDecision=clone(decision);persist();renderResults();}}));
$('show-rejected').addEventListener('change',renderResults);
$('edit-plan').addEventListener('click',()=>{$('plan-json').value=JSON.stringify(plan,null,2);$('editor-error').textContent='';$('editor').showModal();});
$('close-editor').addEventListener('click',()=>$('editor').close());
$('plan-form').addEventListener('submit',e=>{e.preventDefault();try{if($('plan-json').value.length>64000)throw new Error('Plan exceeds 64 KB.');const next=JSON.parse($('plan-json').value);validatePlan(next);plan=next;previous=null;decision=null;lastDecision=null;decisionBase=null;selected=null;persist();$('editor').close();updateStats();renderResults();notify('Plan validated and loaded. Run a new disruption to evaluate recovery.');}catch(e){$('editor-error').textContent=e.message;}});
$('undo').addEventListener('click',()=>{if(!previous)return;const from=fingerprint(plan);plan=previous;previous=null;receipts.push({action:'undo',from,to:fingerprint(plan),at:new Date().toISOString()});decision=null;selected=null;persist();updateStats();renderResults();notify('The last approval was undone locally. The undo is included in your exported decision packet.');});
$('reset').addEventListener('click',()=>{plan=clone(SAMPLE_PLAN);decision=null;selected=null;previous=null;receipts=[];lastDecision=null;decisionBase=null;persist();updateStats();renderResults();notify('Synthetic demo reset. Local approval receipts were cleared.');});
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('export').addEventListener('click',()=>{const packet={schemaVersion:1,application:'DeliveryGuard',generatedAt:new Date().toISOString(),mode:(decision||lastDecision)?.interpretation?.mode||'local-rules',plan,decisionBase,decision:decision||lastDecision,approvalReceipts:receipts,limits:'Prototype; no booking or client notification. Revision checksum is not a security signature.'};const blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='deliveryguard-decision.json';a.click();URL.revokeObjectURL(url);notify('Decision packet exported with inputs, results, trace, and local approval receipts.');});
function view(name){for(const key of ['workspace','evaluations','limits'])$(key+'-view').hidden=key!==name;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('page-title').textContent={workspace:'Recovery',evaluations:'Evaluation harness',limits:'Capabilities & limits'}[name];window.scrollTo({top:0,behavior:'smooth'});if(name==='evaluations')loadEvals();}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.view)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>view(b.dataset.go)));
async function loadEvals(){try{const r=await fetch('./eval-results.json');if(!r.ok)throw new Error('No recorded report');const report=await r.json();$('eval-results').innerHTML=`<div class="eval-summary"><article><strong>${report.passed}/${report.total}</strong><small>Fixture assertions passed</small></article><article><strong>${report.generatedCases}</strong><small>Generated DAG scenarios</small></article><article><strong>${report.liveModelEvaluated?'Yes':'No'}</strong><small>Live model evaluated</small></article></div><section class="card"><div class="section-top"><h2>Recorded evaluation outcomes</h2><span class="pill subtle">${escape(report.generatedAt)}</span></div><p class="muted">${escape(report.scope)}</p><div class="table-wrap"><table><thead><tr><th>Case</th><th>Category</th><th>Expected behavior</th><th>Result</th></tr></thead><tbody>${report.results.map(c=>`<tr><td>${escape(c.name)}</td><td class="eval-category">${escape(c.category)}</td><td>${escape(c.expected)}</td><td class="${c.passed?'eval-pass':'eval-fail'}">${c.passed?'PASS':'FAIL'}</td></tr>`).join('')}</tbody></table></div></section>`;}catch{$('eval-results').innerHTML='<div class="notice error">No evaluation report is available. Run npm run eval to generate the report. No passing tests are assumed.</div>';}}
updateStats();renderResults();
fetch('/api/status').then(r=>r.ok?r.json():null).then(data=>{if(data?.mode==='openai-structured'){apiMode=data.mode;$('live-ai').disabled=false;$('live-status').textContent='available · sends brief and plan constraints to OpenAI';$('mode').textContent='Live AI available';}}).catch(()=>{});

$('run-proof').addEventListener('click',async()=>{const button=$('run-proof');button.disabled=true;button.textContent='Replaying checks…';try{const report=await runProof();$('proof-results').innerHTML=`<p role="status"><strong>${report.passed}/${report.total} live checks passed</strong> · ${escape(report.generatedAt)}</p><p class="muted">${escape(report.scope)}</p><ul>${report.results.map(r=>`<li class="${r.passed?'eval-pass':'eval-fail'}">${r.passed?'PASS':'FAIL'} · ${escape(r.name)}${r.error?' · '+escape(r.error):''}</li>`).join('')}</ul><button class="button secondary" id="export-proof">Download replay evidence</button>`;$('export-proof').addEventListener('click',()=>download(JSON.stringify(report,null,2),'deliveryguard-live-proof.json','application/json'));}catch(e){$('proof-results').textContent='Replay failed: '+e.message;}finally{button.disabled=false;button.textContent='Run live proof suite →';}});
